229	@Repository
230	public class PoolRepository {
231	
232	    private static final BigDecimal FULL = new BigDecimal("100.00");
233	
234	    private final JdbcTemplate jdbc;
235	    private final SettingRepository settings;
236	
237	    public PoolRepository(JdbcTemplate jdbc, SettingRepository settings) {
238	        this.jdbc = jdbc;
239	        this.settings = settings;
240	    }
241	
242	    /** The sheet's pools in the order they were added, each with its members in the order they were added.
243	     *  A pool that is a member of none cuts the sheet's pot; one that is a member of another cuts its cut
244	     *  there (none when that pool has no cuts). */
245	    public List<Pool> list(String sheetId) {
246	        Map<Long, String> names = new LinkedHashMap<>();
247	        Map<Long, List<PoolMember>> members = new LinkedHashMap<>();
248	        Map<Long, Long> parents = new HashMap<>();
249	        jdbc.query("SELECT id, name FROM pool WHERE sheet_id = ? ORDER BY id", rs -> {
250	            names.put(rs.getLong("id"), rs.getString("name"));
251	            members.put(rs.getLong("id"), new ArrayList<>());
252	        }, sheetId);
253	        jdbc.query("SELECT m.pool_id, m.person_id, m.member_pool_id, COALESCE(p.name, q.name) AS name, m.share, "
254	                + "p.retired_from, m.from_date, m.to_date, CASE WHEN (m.from_date IS NULL OR m.from_date <= s.today) "
255	                + "AND (m.to_date IS NULL OR m.to_date >= s.today) THEN TRUE ELSE FALSE END AS current "
256	                + "FROM pool_member m JOIN sheet s ON s.id = m.sheet_id LEFT JOIN person p ON p.id = m.person_id "
257	                + "LEFT JOIN pool q ON q.id = m.member_pool_id WHERE m.sheet_id = ? ORDER BY m.id", rs -> {
258	                    List<PoolMember> of = members.get(rs.getLong("pool_id"));
259	                    if (of != null) {
260	                        Long personId = rs.getObject("person_id") == null ? null : rs.getLong("person_id");
261	                        Long poolId = rs.getObject("member_pool_id") == null ? null : rs.getLong("member_pool_id");
262	                        if (poolId != null) parents.put(poolId, rs.getLong("pool_id"));
263	                        of.add(new PoolMember(personId, poolId, rs.getString("name"),
264	                                rs.getBigDecimal("share").setScale(2).toPlainString(),
265	                                rs.getObject("retired_from") != null,
266	                                rs.getObject("from_date") == null ? null : rs.getDate("from_date").toLocalDate().toString(),
267	                                rs.getObject("to_date") == null ? null : rs.getDate("to_date").toLocalDate().toString(),
268	                                rs.getBoolean("current"), ""));
269	                    }
270	                }, sheetId);
271	        BigDecimal pot = settings.pot(sheetId);
272	        Set<Long> held = new HashSet<>(jdbc.queryForList("SELECT DISTINCT h.person_id FROM person_hold h "
273	                + "JOIN sheet s ON s.id = h.sheet_id WHERE h.sheet_id = ? AND h.from_date <= s.today "
274	                + "AND (h.to_date IS NULL OR h.to_date >= s.today)", Long.class, sheetId));
275	        Map<Long, BigDecimal> totals = new HashMap<>();
276	        for (Map.Entry<Long, List<PoolMember>> pool : members.entrySet()) {
277	            BigDecimal total = BigDecimal.ZERO.setScale(2);
278	            for (PoolMember m : pool.getValue()) {
279	                if (m.current()) total = total.add(new BigDecimal(m.share()));
280	            }
281	            totals.put(pool.getKey(), total);
282	        }
283	        Map<Long, List<PoolMember>> cut = new HashMap<>();
284	        for (Long id : names.keySet()) cutOf(id, members, parents, totals, held, pot, cut, new HashSet<>());
285	        List<Pool> pools = new ArrayList<>();
286	        for (Map.Entry<Long, String> pool : names.entrySet()) {
287	            BigDecimal total = totals.get(pool.getKey());
288	            pools.add(new Pool(pool.getKey(), sheetId, pool.getValue(), cut.get(pool.getKey()),
289	                    total.toPlainString(), total.compareTo(FULL) == 0, parents.get(pool.getKey())));
290	        }
291	        return pools;
292	    }
293	
294	    /** The pool's members with their cuts, worked out (and kept in {@code cut}) after those of the pool above
295	     *  it: its pot is the sheet's pot when it is a member of none, else its cut in the pool above. */
296	    private static List<PoolMember> cutOf(Long id, Map<Long, List<PoolMember>> members, Map<Long, Long> parents,
297	            Map<Long, BigDecimal> totals, Set<Long> held, BigDecimal sheetPot, Map<Long, List<PoolMember>> cut, Set<Long> seen) {
298	        List<PoolMember> done = cut.get(id);
299	        if (done != null) return done;
300	        List<PoolMember> of = members.get(id);
301	        BigDecimal pot = null;
302	        Long parent = parents.get(id);
303	        if (parent == null) {
304	            pot = sheetPot;
305	        } else if (seen.add(id) && members.containsKey(parent)) {
306	            for (PoolMember m : cutOf(parent, members, parents, totals, held, sheetPot, cut, seen)) {
307	                if (id.equals(m.poolId()) && !m.cut().isEmpty()) pot = new BigDecimal(m.cut());
308	            }
309	        }
310	        List<PoolMember> result = pot != null && totals.get(id).compareTo(FULL) == 0 ? cut(of, pot, held) : of;
311	        cut.put(id, result);
312	        return result;
313	    }
314	
315	    /** The members with their cuts of the pot. A member with a cut is one neither retired nor on a hold in
316	     *  force on the sheet's today ({@code held}); the others' cut is 0.00, but a member whose dates do not
317	     *  include the sheet's today is left out entirely (cut ""), as is every member when each current member
318	     *  is retired (the pool shows no cuts). Each member with a cut gets the pot
319	     *  times their share over the shares of the members with a cut added up, rounded half to even to two
320	     *  decimals; the remainder goes to the member with the smallest non-zero cut (the latest added on a tie; a
321	     *  member with no cut gets none), or to the last member with a cut and a share when no cut is non-zero, so the cuts total exactly the pot (all 0.00 when no member has a cut). */
322	    private static List<PoolMember> cut(List<PoolMember> members, BigDecimal pot, Set<Long> held) {
323	        if (members.stream().anyMatch(PoolMember::current)
324	                && members.stream().filter(PoolMember::current).allMatch(PoolMember::retired)) {
325	            return members.stream().map(m -> m.withCut("")).toList();
326	        }
327	        BigDecimal[] cuts = new BigDecimal[members.size()];
328	        boolean[] cutting = new boolean[members.size()];
329	        BigDecimal shares = BigDecimal.ZERO.setScale(2);
330	        for (int i = 0; i < members.size(); i++) {
331	            PoolMember m = members.get(i);
332	            cutting[i] = m.current() && !m.retired() && (m.personId() == null || !held.contains(m.personId()));
333	            if (cutting[i]) shares = shares.add(new BigDecimal(m.share()));
334	        }
335	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
336	        int smallest = -1;
337	        int last = -1;
338	        for (int i = 0; i < members.size(); i++) {
339	            BigDecimal share = new BigDecimal(members.get(i).share());
340	            cuts[i] = cutting[i] ? pot.multiply(share).divide(shares, 2, RoundingMode.HALF_EVEN)
341	                    : BigDecimal.ZERO.setScale(2);
342	            sum = sum.add(cuts[i]);
343	            if (cutting[i] && share.signum() != 0) last = i;
344	            if (cutting[i] && cuts[i].signum() != 0
345	                    && (smallest < 0 || cuts[i].compareTo(cuts[smallest]) <= 0)) {
346	                smallest = i;
347	            }
348	        }
349	        int to = smallest >= 0 ? smallest : last;
350	        if (to >= 0) cuts[to] = cuts[to].add(pot.subtract(sum));
351	        List<PoolMember> cut = new ArrayList<>();
352	        for (int i = 0; i < members.size(); i++) {
353	            cut.add(members.get(i).withCut(members.get(i).current() ? cuts[i].toPlainString() : ""));
354	        }
355	        return cut;
356	    }
